@step(tools={"ledger.read"})                 # least privilege: read only
def fetch_invoice(q: InvoiceQuery) -> Invoice: ...

@step(tools={"fx.read"})
def convert_total(inv: Invoice) -> ConvertedTotal: ...

@step(tools={"payments.write"})              # the only step that can pay
def pay(total: ConvertedTotal) -> Receipt: ...

pay_invoice = compose(fetch_invoice, convert_total, pay)  # type-checked chain
